package ru.folio.notes;
import org.json.*;
import java.util.*;

public final class ContentModelTests {
    static int assertions;static void check(boolean yes,String label){if(!yes)throw new AssertionError(label);assertions++;}
    public static void main(String[] args)throws Exception{
        Ink.Doc doc=new Ink.Doc();Ink.Page p=doc.page();Ink.Layer l=new Ink.Layer();l.id="upper";l.name="Набросок";p.layers.add(l);p.activeLayer=l.id;p.bookmark="Глава 1";l.locked=true;
        Ink.Stroke a=new Ink.Stroke();a.tool="tape";a.texture=4;a.layer=l.id;a.points.add(new Ink.Pt(20,40,.6f,.4f,.7f));Ink.Stroke b=a.copy();b.layer="base";p.strokes.add(a);p.strokes.add(b);p.order();check(p.strokes.get(0)==b&&p.strokes.get(1)==a,"layer z order");check(!p.editable(a)&&p.visible(a)&&p.editable(b),"lock protects only its layer");check(!p.writable(),"cannot draw into locked active layer");
        Ink.History h=new Ink.History();h.before(p);l.locked=false;l.visible=false;Ink.Page undo=h.undo(p);check(undo.layers.get(1).locked&&undo.layers.get(1).visible,"layer history deep copies flags");check(!h.redo(undo).layers.get(1).visible,"layer redo");check(!p.visible(a)&&!p.editable(a),"hidden layer protection");
        Ink.Audio r=new Ink.Audio();r.file="sample_1.m4a";r.page=p.id;r.duration=34500;r.name="Мысль";doc.audio.add(r);Ink.Doc restored=Ink.Doc.parse(new JSONObject(doc.json().toString()));check(restored.page().id.equals(p.id),"page IDs retained for audio and bookmarks");check(restored.page().bookmark.equals(p.bookmark),"bookmark roundtrip");check(restored.page().activeLayer.equals("upper"),"active layer roundtrip");check(restored.page().layers.size()==2&&!restored.page().layers.get(1).visible,"layer visibility roundtrip");check(restored.page().strokes.get(1).texture==4,"material roundtrip");check(restored.audio.get(0).duration==34500&&restored.audio.get(0).page.equals(p.id),"audio metadata roundtrip");
        Ink.Doc copy=doc.copy();copy.audio.get(0).name="Другое";copy.page().layers.get(1).visible=true;check(doc.audio.get(0).name.equals("Мысль")&&!p.layers.get(1).visible,"snapshot metadata isolated from later edits");
        for(int id=0;id<=5;id++){a.texture=id;check(a.copy().texture==id&&a.translated(2,3).texture==id&&a.transformed(0,0,2,1).texture==id,"material survives editing "+id);}
        a.cuts.add(new Ink.Cut(20,40,5,30,50));Ink.Stroke mirror=a.mirrored(100,100,true).mirrored(100,100,true);check(Math.abs(mirror.points.get(0).x-a.points.get(0).x)<.001&&Math.abs(InkGeometry.delta(mirror.points.get(0).angle,a.points.get(0).angle))<.001,"double mirror restores position and roll");check(mirror.cuts.get(0).x==20&&mirror.cuts.get(0).z==30&&mirror.texture==a.texture,"mirror preserves masks/material");JSONObject legacy=doc.json();JSONObject oldPage=legacy.getJSONArray("pages").getJSONObject(0);oldPage.remove("layers");oldPage.remove("activeLayer");oldPage.remove("bookmark");legacy.remove("audio");for(int i=0;i<oldPage.getJSONArray("strokes").length();i++){JSONObject old=oldPage.getJSONArray("strokes").getJSONObject(i);old.remove("texture");old.remove("layer");}Ink.Doc migrated=Ink.Doc.parse(legacy);check(migrated.page().layers.size()==1&&migrated.page().activeLayer.equals("base")&&migrated.page().strokes.get(0).texture==0,"old documents get base layer and plain tape");check(migrated.audio.isEmpty()&&migrated.page().bookmark.isEmpty(),"old documents remain without audio/bookmarks");
        JSONObject bad=doc.json();bad.getJSONArray("pages").getJSONObject(0).getJSONArray("layers").put(new JSONObject().put("id","upper"));boolean rejected=false;try{Ink.Doc.parse(bad);}catch(JSONException e){rejected=true;}check(rejected,"duplicate layer IDs rejected");
        bad=doc.json();bad.getJSONArray("audio").getJSONObject(0).put("file","../private.m4a");rejected=false;try{Ink.Doc.parse(bad);}catch(JSONException e){rejected=true;}check(rejected,"unsafe audio paths rejected");
        bad=doc.json();bad.getJSONArray("pages").getJSONObject(0).put("activeLayer","missing");check(Ink.Doc.parse(bad).page().activeLayer.equals("base"),"unknown active layer falls back safely");
        bad=doc.json();bad.getJSONArray("pages").getJSONObject(0).getJSONArray("strokes").getJSONObject(1).put("layer","missing").put("texture",99);Ink.Stroke safe=Ink.Doc.parse(bad).page().strokes.get(0);check(safe.layer.equals("base"),"orphan stroke remains accessible on base layer");
        System.out.println("PASS "+assertions+" content model assertions: materials, layer order/visibility/protection, deep history, page bookmarks, audio links, legacy migration and malformed imports. Desktop JVM; Android checks separate.");
    }
}
